import java.util.*;
import org.simplepoint.platform.composition.*;
import org.simplepoint.plugin.personal.rest.PersonalController;
import org.simplepoint.plugin.personal.rest.configuration.PersonalHttpModule;
import org.simplepoint.plugin.notification.rest.controller.NotificationInboxController;
import org.simplepoint.plugin.notification.rest.configuration.NotificationHttpModule;
import org.simplepoint.plugin.notification.rest.push.NotificationSseBroker;
import org.simplepoint.plugin.notification.api.service.NotificationDeliveryService;

public class VerifyPersonalNotificationHttpArtifacts {
  public static void main(String[] args) throws Exception {
    var loader = VerifyPersonalNotificationHttpArtifacts.class.getClassLoader();
    var catalog = ModuleCatalog.discover(loader);
    var domain = catalog.plan(List.of("notification"));
    if (!domain.modules().stream().map(ModuleDescriptor::id).toList().equals(List.of("personal", "notification"))
        || !ModuleHttpPlan.from(domain).routes().isEmpty())
      throw new AssertionError("Domain-only closure includes HTTP");
    for (Class<?> type : List.of(PersonalController.class, NotificationInboxController.class, NotificationSseBroker.class))
      if (domain.ownerOf(type).isPresent()) throw new AssertionError("Domain scans browser adapters");
    var adapters = catalog.plan(List.of("personal-http", "notification-http"));
    var routes = ModuleHttpPlan.from(adapters).routes();
    if (!routes.equals(Map.of("personal-http", Set.of("/common/personal"), "notification-http",
        Set.of("/common/notifications", "/common/system/notifications"))))
      throw new AssertionError("Public route ownership changed: " + routes);
    if (catalog.plan(List.of("notification-http")).modules().stream().anyMatch(m -> m.id().equals("personal-http")))
      throw new AssertionError("Notification opens optional personal routes");
    if (!"notification".equals(adapters.ownerOf(NotificationDeliveryService.class).orElseThrow().id()))
      throw new AssertionError("Domain RPC owner changed");
    for (Class<?> type : List.of(PersonalHttpModule.class, NotificationHttpModule.class)) {
      if (type.getAnnotation(ModuleMigrations.class).ownsSchema())
        throw new AssertionError("HTTP adapter claimed schema");
      if (Collections.list(loader.getResources(type.getName().replace('.', '/') + ".class")).size() != 1)
        throw new AssertionError("Missing/duplicate packaged adapter");
    }
    if (!org.springframework.beans.factory.DisposableBean.class.isAssignableFrom(NotificationSseBroker.class))
      throw new AssertionError("SSE lifecycle missing from packaged class");
    System.out.println("Installed Common verified: explicit personal-http/notification-http, exclusive packages, exact derived public routes, domain-only closure without browser adapters, unchanged notification RPC owner, no HTTP schema ownership, unique classes and packaged SSE shutdown lifecycle.");
  }
}
